-- UNIK: обложка (пейзаж + логотип UNIK) и настоящие карты игры на предмете «Карты». Выполнить один раз.
alter table public.games add column if not exists item_img text check (item_img is null or char_length(item_img) <= 150000);
alter table public.games add column if not exists has_iart boolean generated always as (item_img is not null) stored;
update public.games set cover = 'img:044dd4f2f806', cover_img = 'data:image/jpeg;base64,', item_img = 'data:image/jpeg;base64,', updated_at = now() where id = 'unik';
